package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.ui.McpInstallPreviewRules;
import dev.pocketengine.ui.McpLocalDiscoveryRules;
import dev.pocketengine.ui.McpLocalPreparation;
import dev.pocketengine.ui.McpLocalReviewed;
import dev.pocketengine.ui.McpLocalSelection;
import java.util.UUID;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Client correlation consumes the actual native-owned review; it cannot mint its approval. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalDiscoveryPresentationTest {
    private static final McpLocalDiscoveryRules RULES=McpLocalDiscoveryRules.INSTANCE;
    private static final class View implements AutoCloseable {
        final McpLocalDiscoveryOwnerTest.Fixture nativeOwner=new McpLocalDiscoveryOwnerTest.Fixture();final JSONObject body=nativeOwner.prepare(),snapshot=nativeOwner.f.plugins.snapshot();final String request=UUID.randomUUID().toString();final McpLocalSelection selection=selection(nativeOwner.f.config);final McpLocalPreparation preparation=new McpLocalPreparation(request,selection.configuration().toString(),7);final JSONObject envelope=envelope(request,body);final long now=System.currentTimeMillis();
        View()throws Exception{}
        McpLocalReviewed frozen(){return RULES.freeze(preparation,selection,7,snapshot,envelope,now);}
        public void close()throws Exception{nativeOwner.close();}
    }
    private static McpLocalSelection selection(JSONObject c)throws Exception{return new McpLocalSelection(c.getString("id"),c.getString("name"),c.getString("checkoutId"),c.getString("expectedSourceDigest"),c.getString("executable"),c.getJSONArray("argv").toString());}
    private static JSONObject envelope(String request,JSONObject value)throws Exception{return new JSONObject().put("requestId",request).put("ok",true).put("result",new JSONObject(value.toString()));}
    @Test public void actualNativeReviewPinsAllCopyFlagsAndCanProduceOnlyTheTwoConfirmationReferences()throws Exception{try(View v=new View()){McpLocalReviewed frozen=v.frozen();assertNotNull(frozen);JSONObject payload=RULES.confirmPayload(frozen,v.selection,7,v.snapshot,v.envelope,v.now);assertEquals(v.body.getString("reviewId"),payload.getString("reviewId"));assertEquals(v.body.getString("planDigest"),payload.getString("planDigest"));assertEquals(2,payload.length());assertFalse(payload.has("approved"));assertFalse(payload.has("argv"));assertEquals(0,v.nativeOwner.f.tasks.list().length());}}
    @Test public void anotherRequestOrFailedEnvelopeCannotBecomeTheCurrentReview()throws Exception{try(View v=new View()){assertNull(RULES.freeze(v.preparation,v.selection,7,v.snapshot,envelope("wrong",v.body),v.now));assertNull(RULES.freeze(v.preparation,v.selection,7,v.snapshot,new JSONObject(v.envelope.toString()).put("ok",false),v.now));assertNull(RULES.freeze(null,v.selection,7,v.snapshot,v.envelope,v.now));}}
    @Test public void editedInputRevisionSourceOrArgumentsInvalidateTheFrozenDisplay()throws Exception{try(View v=new View()){McpLocalReviewed frozen=v.frozen();assertNull(RULES.current(frozen,v.selection,8,v.snapshot,v.envelope,v.now));for(String field:new String[]{"id","name","expectedSourceDigest"}){JSONObject config=v.selection.configuration();config.put(field,field.equals("expectedSourceDigest")?"0".repeat(64):"changed");assertNull(RULES.current(frozen,selection(config),7,v.snapshot,v.envelope,v.now));}JSONObject config=v.selection.configuration();config.getJSONArray("argv").put("new-public-argument");assertNull(RULES.current(frozen,selection(config),7,v.snapshot,v.envelope,v.now));}}
    @Test public void expiryCannotBeExtendedByKeepingAnOldSuccessfulEnvelope()throws Exception{try(View v=new View()){assertNull(RULES.current(v.frozen(),v.selection,7,v.snapshot,v.envelope,v.body.getLong("reviewExpiresAt")));assertThrows(IllegalStateException.class,()->RULES.confirmPayload(v.frozen(),v.selection,7,v.snapshot,v.envelope,v.body.getLong("reviewExpiresAt")));}}
    @Test public void absentInstallationRaceInvalidatesBeforeTheConfirmationPayloadExists()throws Exception{try(View v=new View()){McpLocalReviewed frozen=v.frozen();v.nativeOwner.f.installEcho();assertNull(RULES.current(frozen,v.selection,7,v.nativeOwner.f.plugins.snapshot(),v.envelope,v.now));}}
    @Test public void legitimateInstalledRevisionZeroIsSupportedButFractionalOrReplacedRefsAreNot()throws Exception{try(McpLocalDiscoveryOwnerTest.Fixture x=new McpLocalDiscoveryOwnerTest.Fixture()){x.f.installEcho();JSONObject body=x.prepare(),snapshot=x.f.plugins.snapshot();McpLocalSelection selection=selection(x.f.config);String request=UUID.randomUUID().toString();McpLocalPreparation preparation=new McpLocalPreparation(request,selection.configuration().toString(),1);JSONObject reply=envelope(request,body);McpLocalReviewed frozen=RULES.freeze(preparation,selection,1,snapshot,reply,System.currentTimeMillis());assertNotNull(frozen);assertEquals(0,body.getLong("expectedStateRevision"));JSONObject changed=new JSONObject(snapshot.toString());changed.getJSONArray("plugins").getJSONObject(0).put("stateRevision",0.5);assertNull(RULES.current(frozen,selection,1,changed,reply,System.currentTimeMillis()));changed=new JSONObject(snapshot.toString());changed.getJSONArray("plugins").getJSONObject(0).put("installationId",UUID.randomUUID().toString());assertNull(RULES.current(frozen,selection,1,changed,reply,System.currentTimeMillis()));}}
    @Test public void mutableEnvelopeAliasCannotChangeRiskOrArgvBehindTheDisplayedReview()throws Exception{try(View v=new View()){McpLocalReviewed frozen=v.frozen();JSONObject body=v.envelope.getJSONObject("result");body.put("risk","altered source description");assertNull(RULES.current(frozen,v.selection,7,v.snapshot,v.envelope,v.now));assertTrue(new JSONObject(frozen.getBody()).getString("risk").contains("同UID"));}}
    @Test public void promotedAuthorityOrFakeSandboxFlagsCannotBePresentedAsAValidReview()throws Exception{try(View v=new View()){for(String field:new String[]{"executionAuthorized","osSandbox","hiddenFilesIncluded","dependencyCachesIncluded","wholeCheckoutVersion","installationAuthorized","toolInvocationAuthorized","modelInferenceAllowed","credentialsSupported","environmentInputsSupported","programStarted"}){JSONObject body=new JSONObject(v.body.toString()).put(field,true);assertNull(field,RULES.freeze(v.preparation,v.selection,7,v.snapshot,envelope(v.request,body),v.now));}}}
    @Test public void mismatchedCopyOrScopeDigestCannotBecomeTheConfirmationSource()throws Exception{try(View v=new View()){for(String field:new String[]{"executionCopyId","configurationId","planDigest","configurationDigest","argvDigest"}){JSONObject body=new JSONObject(v.body.toString()).put(field,field.endsWith("Id")?UUID.randomUUID().toString():"0".repeat(64));assertNull(field,RULES.freeze(v.preparation,v.selection,7,v.snapshot,envelope(v.request,body),v.now));}JSONObject body=new JSONObject(v.body.toString()).put("unexpectedScope",true);assertNull(RULES.freeze(v.preparation,v.selection,7,v.snapshot,envelope(v.request,body),v.now));}}
    @Test public void operationDisplayRequiresTheActualOriginalTaskAndMatchingRequest()throws Exception{try(McpLocalDiscoveryOwnerTest.Fixture x=new McpLocalDiscoveryOwnerTest.Fixture()){McpLocalDiscovery.Confirmed confirmed=x.f.confirmed();RunControl original=new RunControl();JSONObject row=x.f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,original),view=McpLocalDiscoveryPipe.publicView(row);String request=UUID.randomUUID().toString(),id=confirmed.actionId();assertNotNull(RULES.operation(request,envelope(request,view),id));assertNull(RULES.operation("other",envelope(request,view),id));assertNull(RULES.operation(request,envelope(request,view),UUID.randomUUID().toString()));assertNull(RULES.operation(request,envelope(request,new JSONObject(view.toString()).put("replayAllowed",true)),id));}}
    @Test public void argvParsingIsStrictAndNeverFallsBackToShellOrAbsoluteHostPaths()throws Exception{JSONObject config=new JSONObject().put("id","local").put("name","Local").put("checkoutId",UUID.randomUUID().toString()).put("expectedSourceDigest","a".repeat(64)).put("executable","python3").put("argv",new JSONArray().put("server.py"));McpLocalSelection valid=selection(config);assertEquals("server.py",valid.configuration().getJSONArray("argv").getString(0));for(String argv:new String[]{"[\"server.py\"] trailing","[\"/tmp/host.py\"]","[\"../host.py\"]","[\".hidden.py\"]","[\"-c\",\"code\"]","[4]","[]"}){McpLocalSelection bad=new McpLocalSelection(valid.getId(),valid.getName(),valid.getCheckout(),valid.getSource(),"python3",argv);assertThrows(argv,Exception.class,bad::configuration);}}
    @Test public void aSealedUiBodyCannotBeConfirmedFromAnotherPreparationConfiguration()throws Exception{try(View v=new View()){JSONObject other=v.selection.configuration().put("name","Other source");McpLocalPreparation mismatched=new McpLocalPreparation(v.request,other.toString(),7);assertNull(RULES.freeze(mismatched,v.selection,7,v.snapshot,v.envelope,v.now));assertEquals(0,v.nativeOwner.f.tasks.list().length());}}
}
